下面是一个可直接使用的网页版温度换算小工具。把代码保存为 `temperature.html`，双击用浏览器打开即可。

```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>温度换算小工具</title>
  <style>
    :root {
      color-scheme: light dark;
      --bg: #f4f6fb;
      --card: #ffffff;
      --text: #1f2937;
      --muted: #6b7280;
      --border: #d1d5db;
      --primary: #2563eb;
      --danger: #dc2626;
    }

    @media (prefers-color-scheme: dark) {
      :root {
        --bg: #0f172a;
        --card: #111827;
        --text: #e5e7eb;
        --muted: #9ca3af;
        --border: #374151;
        --primary: #60a5fa;
        --danger: #f87171;
      }
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 20px;
      background: var(--bg);
      color: var(--text);
      font-family: system-ui, -apple-system, "Segoe UI", Roboto,
        "PingFang SC", "Microsoft YaHei", sans-serif;
    }

    .card {
      width: min(100%, 460px);
      background: var(--card);
      border-radius: 18px;
      padding: 24px;
      box-shadow: 0 12px 36px rgba(0, 0, 0, 0.12);
    }

    h1 {
      margin: 0 0 6px;
      font-size: 1.45rem;
    }

    .hint {
      margin: 0 0 20px;
      color: var(--muted);
      font-size: 0.92rem;
    }

    .field {
      margin-bottom: 14px;
    }

    label {
      display: block;
      margin-bottom: 6px;
      font-weight: 600;
      font-size: 0.92rem;
    }

    input {
      width: 100%;
      padding: 12px 14px;
      border: 1px solid var(--border);
      border-radius: 12px;
      background: transparent;
      color: var(--text);
      font-size: 1.05rem;
      outline: none;
    }

    input:focus {
      border-color: var(--primary);
      box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18);
    }

    .error {
      min-height: 1.3em;
      margin: 4px 0 12px;
      color: var(--danger);
      font-size: 0.9rem;
    }

    button {
      width: 100%;
      padding: 11px 14px;
      border: 0;
      border-radius: 12px;
      background: var(--primary);
      color: #fff;
      font-size: 1rem;
      font-weight: 600;
      cursor: pointer;
    }

    button:hover {
      filter: brightness(1.05);
    }

    button:active {
      transform: translateY(1px);
    }
  </style>
</head>
<body>
  <main class="card">
    <h1>温度换算小工具</h1>
    <p class="hint">在任意一栏输入温度，其余两栏会自动换算。</p>

    <div class="field">
      <label for="celsius">摄氏度（°C）</label>
      <input id="celsius" type="number" step="any" inputmode="decimal" placeholder="例如：25" />
    </div>

    <div class="field">
      <label for="fahrenheit">华氏度（°F）</label>
      <input id="fahrenheit" type="number" step="any" inputmode="decimal" placeholder="例如：77" />
    </div>

    <div class="field">
      <label for="kelvin">开尔文（K）</label>
      <input id="kelvin" type="number" step="any" inputmode="decimal" placeholder="例如：298.15" />
    </div>

    <div id="message" class="error" role="alert"></div>
    <button id="reset" type="button">清空</button>
  </main>

  <script>
    const inputs = {
      c: document.getElementById("celsius"),
      f: document.getElementById("fahrenheit"),
      k: document.getElementById("kelvin")
    };

    const message = document.getElementById("message");

    const absoluteZero = {
      c: -273.15,
      f: -459.67,
      k: 0
    };

    const names = {
      c: "摄氏度",
      f: "华氏度",
      k: "开尔文"
    };

    function formatNumber(n) {
      if (!Number.isFinite(n)) return "";
      return String(Number(n.toFixed(8)));
    }

    function clearOthers(source) {
      for (const key of Object.keys(inputs)) {
        if (key !== source) {
          inputs[key].value = "";
        }
      }
    }

    function convert(source) {
      const raw = inputs[source].value.trim();
      message.textContent = "";

      if (raw === "") {
        clearOthers(source);
        return;
      }

      const value = Number(raw);

      if (!Number.isFinite(value)) {
        message.textContent = "请输入有效数字。";
        clearOthers(source);
        return;
      }

      if (value < absoluteZero[source]) {
        message.textContent =
          `${names[source]}不能低于绝对零度（${absoluteZero[source]}）。`;
        clearOthers(source);
        return;
      }

      let c, f, k;

      if (source === "c") {
        c = value;
        f = c * 9 / 5 + 32;
        k = c + 273.15;
      } else if (source === "f") {
        c = (value - 32) * 5 / 9;
        f = value;
        k = c + 273.15;
      } else {
        k = value;
        c = k - 273.15;
        f = c * 9 / 5 + 32;
      }

      if (c < -273.15 - 1e-9 || f < -459.67 - 1e-9 || k < -1e-9) {
        message.textContent = "温度不能低于绝对零度。";
        clearOthers(source);
        return;
      }

      if (source !== "c") inputs.c.value = formatNumber(c);
      if (source !== "f") inputs.f.value = formatNumber(f);
      if (source !== "k") inputs.k.value = formatNumber(k);
    }

    inputs.c.addEventListener("input", () => convert("c"));
    inputs.f.addEventListener("input", () => convert("f"));
    inputs.k.addEventListener("input", () => convert("k"));

    document.getElementById("reset").addEventListener("click", () => {
      inputs.c.value = "";
      inputs.f.value = "";
      inputs.k.value = "";
      message.textContent = "";
      inputs.c.focus();
    });
  </script>
</body>
</html>
```

换算公式：

- 摄氏度转华氏度：`°F = °C × 9 / 5 + 32`
- 华氏度转摄氏度：`°C = (°F - 32) × 5 / 9`
- 摄氏度转开尔文：`K = °C + 273.15`
- 开尔文转摄氏度：`°C = K - 273.15`

还加入了绝对零度校验，低于绝对零度会提示错误。

这是可直接运行的番茄钟HTML代码，默认25分钟专注、5分钟休息，支持自动切换和声音提醒。
```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>番茄钟</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    --accent: #ff6b6b;
    --accent-soft: rgba(255, 107, 107, 0.14);
    min-height: 100vh;
    display: grid;
    place-items: center;
    padding: 24px;
    background: radial-gradient(circle at 50% 0%, #1d2029 0%, #101217 70%);
    color: #e8eaf0;
    font-family: system-ui, -apple-system, "PingFang SC", "Microsoft YaHei", sans-serif;
    -webkit-font-smoothing: antialiased;
    transition: background 0.4s;
  }

  /* 休息模式换配色 */
  body.break {
    --accent: #4ecdc4;
    --accent-soft: rgba(78, 205, 196, 0.14);
  }

  .app { width: min(100%, 400px); }

  /* ---------- 顶部模式切换 ---------- */
  .tabs {
    display: flex;
    gap: 6px;
    padding: 6px;
    margin-bottom: 28px;
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.045);
    border: 1px solid rgba(255, 255, 255, 0.06);
  }

  .tab {
    flex: 1;
    padding: 11px 8px;
    border: 0;
    border-radius: 11px;
    background: transparent;
    color: #8b91a0;
    font: 500 14px/1 inherit;
    font-family: inherit;
    cursor: pointer;
    transition: background 0.25s, color 0.25s;
  }

  .tab.active {
    background: var(--accent-soft);
    color: var(--accent);
    font-weight: 600;
  }

  /* ---------- 圆环计时器 ---------- */
  .dial {
    position: relative;
    width: 100%;
    aspect-ratio: 1 / 1;
  }

  .dial svg { width: 100%; height: 100%; display: block; }

  .track { fill: none; stroke: rgba(255, 255, 255, 0.07); stroke-width: 10; }

  .progress {
    fill: none;
    stroke: var(--accent);
    stroke-width: 10;
    stroke-linecap: round;
    transform: rotate(-90deg);
    transform-origin: 120px 120px;
    transition: stroke-dashoffset 0.1s linear, stroke 0.4s;
    filter: drop-shadow(0 0 10px var(--accent-soft));
  }

  .readout {
    position: absolute;
    inset: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 10px;
    pointer-events: none;
  }

  .time {
    font-size: clamp(46px, 15vw, 66px);
    font-weight: 600;
    line-height: 1;
    letter-spacing: 0.01em;
    font-variant-numeric: tabular-nums;
    font-feature-settings: "tnum";
  }

  .label {
    font-size: 13px;
    letter-spacing: 0.28em;
    text-indent: 0.28em;
    color: var(--accent);
    transition: color 0.4s;
  }

  /* ---------- 按钮 ---------- */
  .controls { display: flex; gap: 12px; margin-top: 30px; }

  .btn {
    flex: 1;
    padding: 15px 20px;
    border: 1px solid transparent;
    border-radius: 15px;
    font: 600 16px/1 inherit;
    font-family: inherit;
    cursor: pointer;
    transition: transform 0.12s, background 0.25s, box-shadow 0.25s, border-color 0.25s;
  }

  .btn:active { transform: scale(0.97); }

  .btn.primary {
    background: var(--accent);
    color: #14161d;
    box-shadow: 0 10px 28px -10px var(--accent);
  }

  .btn.ghost {
    flex: 0 0 96px;
    background: transparent;
    border-color: rgba(255, 255, 255, 0.14);
    color: #b9bec9;
  }

  .btn.ghost:hover { background: rgba(255, 255, 255, 0.06); }

  /* ---------- 底部信息 ---------- */
  .meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    margin-top: 26px;
    font-size: 13px;
    color: #858b99;
  }

  .switch {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
    user-select: none;
  }

  .switch input {
    width: 15px;
    height: 15px;
    accent-color: var(--accent);
    cursor: pointer;
  }

  @media (max-width: 340px) {
    .btn.ghost { flex: 0 0 76px; }
  }
</style>
</head>
<body>

<main class="app">
  <header class="tabs">
    <button class="tab active" data-mode="focus">专注 25 分钟</button>
    <button class="tab" data-mode="break">休息 5 分钟</button>
  </header>

  <div class="dial">
    <svg viewBox="0 0 240 240" aria-hidden="true">
      <circle class="track" cx="120" cy="120" r="104"></circle>
      <circle class="progress" id="progress" cx="120" cy="120" r="104"></circle>
    </svg>
    <div class="readout">
      <div class="time" id="time">25:00</div>
      <div class="label" id="label">专注</div>
    </div>
  </div>

  <div class="controls">
    <button class="btn primary" id="startBtn">开始</button>
    <button class="btn ghost" id="resetBtn">重置</button>
  </div>

  <footer class="meta">
    <span id="stats">已完成 0 个番茄</span>
    <label class="switch">
      <input type="checkbox" id="autoStart">
      <span>自动开始下一段</span>
    </label>
  </footer>
</main>

<script>
(() => {
  'use strict';

  /* ---------------- 配置 ---------------- */
  const DURATIONS = { focus: 25 * 60, break: 5 * 60 };  // 秒
  const LABELS    = { focus: '专注',   break: '休息'   };
  const R    = 104;
  const CIRC = 2 * Math.PI * R;

  /* ---------------- 元素 ---------------- */
  const timeEl     = document.getElementById('time');
  const labelEl    = document.getElementById('label');
  const progressEl = document.getElementById('progress');
  const startBtn   = document.getElementById('startBtn');
  const resetBtn   = document.getElementById('resetBtn');
  const autoStartEl= document.getElementById('autoStart');
  const statsEl    = document.getElementById('stats');
  const tabs       = Array.from(document.querySelectorAll('.tab'));

  progressEl.style.strokeDasharray = CIRC;

  /* ---------------- 状态 ---------------- */
  let mode      = 'focus';
  let duration  = DURATIONS[mode];
  let remaining = duration;   // 剩余秒数（浮点）
  let endTime   = 0;          // 结束时间戳
  let running   = false;
  let tickId    = null;
  let completed = 0;

  /* ---------------- 渲染 ---------------- */
  function render() {
    const total = Math.max(0, Math.ceil(remaining));
    const mm = String(Math.floor(total / 60)).padStart(2, '0');
    const ss = String(total % 60).padStart(2, '0');
    const text = `${mm}:${ss}`;

    timeEl.textContent  = text;
    labelEl.textContent = LABELS[mode];
    document.title      = `${text} · ${LABELS[mode]} | 番茄钟`;

    progressEl.style.strokeDashoffset = CIRC * (1 - remaining / duration);

    if (running) {
      startBtn.textContent = '暂停';
    } else {
      startBtn.textContent = (remaining >= duration - 0.01) ? '开始' : '继续';
    }
  }

  /* ---------------- 计时控制 ---------------- */
  function start() {
    if (running) return;
    if (remaining <= 0) remaining = duration;

    unlockAudio();                       // 用户手势中解锁音频
    endTime = Date.now() + remaining * 1000;
    running = true;
    tickId = setInterval(tick, 100);
    render();
  }

  function pause() {
    if (!running) return;
    remaining = Math.max(0, (endTime - Date.now()) / 1000);
    running = false;
    clearInterval(tickId);
    tickId = null;
    render();
  }

  function tick() {
    const left = (endTime - Date.now()) / 1000;
    if (left <= 0) {
      remaining = 0;
      running = false;
      clearInterval(tickId);
      tickId = null;
      render();
      finish();
      return;
    }
    remaining = left;
    render();
  }

  function finish() {
    playChime();
    if (mode === 'focus') {
      completed += 1;
      statsEl.textContent = `已完成 ${completed} 个番茄`;
    }
    switchMode(mode === 'focus' ? 'break' : 'focus', autoStartEl.checked);
  }

  function switchMode(next, autoStart = false) {
    clearInterval(tickId);
    tickId = null;
    running = false;

    mode = next;
    duration = DURATIONS[mode];
    remaining = duration;

    document.body.classList.toggle('break', mode === 'break');
    tabs.forEach(t => t.classList.toggle('active', t.dataset.mode === mode));

    render();
    if (autoStart) start();
  }

  function reset() {
    clearInterval(tickId);
    tickId = null;
    running = false;
    remaining = duration;
    render();
  }

  /* ---------------- 提示音 ---------------- */
  let audioCtx = null;

  function unlockAudio() {
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      if (!audioCtx) audioCtx = new AC();
      if (audioCtx.state === 'suspended') audioCtx.resume();
    } catch (_) { /* 忽略 */ }
  }

  function playChime() {
    unlockAudio();
    if (!audioCtx) return;

    const notes = [880, 1108.73, 1318.51];   // A5 - C#6 - E6
    notes.forEach((freq, i) => {
      const t = audioCtx.currentTime + i * 0.17;
      const osc  = audioCtx.createOscillator();
      const gain = audioCtx.createGain();

      osc.type = 'sine';
      osc.frequency.value = freq;

      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(0.28, t + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.55);

      osc.connect(gain);
      gain.connect(audioCtx.destination);
      osc.start(t);
      osc.stop(t + 0.6);
    });
  }

  /* ---------------- 事件绑定 ---------------- */
  startBtn.addEventListener('click', () => {
    running ? pause() : start();
  });

  resetBtn.addEventListener('click', reset);

  tabs.forEach(tab => {
    tab.addEventListener('click', () => {
      if (tab.dataset.mode === mode) {
        reset();               // 点击当前模式 → 重置
      } else {
        switchMode(tab.dataset.mode, false);
      }
    });
  });

  // 空格开始/暂停，R 重置
  window.addEventListener('keydown', (e) => {
    const tag = document.activeElement && document.activeElement.tagName;
    if (tag === 'INPUT' || tag === 'BUTTON') return;

    if (e.code === 'Space') {
      e.preventDefault();
      running ? pause() : start();
    } else if (e.key === 'r' || e.key === 'R') {
      reset();
    }
  });

  // 标签页切回时立即校准显示（后台定时器会被浏览器节流）
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden && running) tick();
  });

  /* ---------------- 初始化 ---------------- */
  render();
})();
</script>
</body>
</html>
```
### 计时工具的核心操作与反馈

打开就能用的计时器，操作集中在按钮和圆环上。

- **模式切换**：顶部两个标签分别切换“专注 25 分钟”和“休息 5 分钟”，当前模式的配色会跟着变，专注是红色，休息是青色。
- **开始与暂停**：中央大按钮会根据状态显示“开始/暂停/继续”。按空格键也能快速开始或暂停，重置则用 R 键。
- **圆环进度**：外圈进度条会随着剩余时间缩短，同时剩余分钟秒数显示在圆环中央，页面标题也会同步更新。
- **自动衔接**：勾选“自动开始下一段”后，当前模式结束后会自动切换到另一模式并立即计时；每次专注结束会累计完成番茄数。
- **声音提示**：一段计时结束时，会用 Web Audio 发出三声渐弱提示音，不需要额外音频文件。
---

**优化建议：** 您可以在代码开头的 `DURATIONS` 对象里修改专注和休息时长（单位是秒），比如改成 30 分钟就写 `30 * 60`。

这是一个可直接运行的HTML文档，模拟平抛运动，您可以拖动滑块实时调整初速度、高度和重力加速度，直观观察小球轨迹变化。
```html
<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>平抛运动模拟</title>
<style>
  * { box-sizing: border-box; }
  html, body { margin: 0; height: 100%; }
  body {
    font-family: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
    background: #070b12; color: #e6edf7;
    display: flex; height: 100vh; overflow: hidden;
  }
  #stage { flex: 1 1 auto; position: relative; min-width: 0; }
  canvas { display: block; width: 100%; height: 100%; }

  .panel {
    width: 312px; flex: 0 0 312px;
    background: #0d1523;
    border-left: 1px solid #1d2b40;
    padding: 18px 16px 24px;
    overflow-y: auto;
    display: flex; flex-direction: column; gap: 16px;
  }
  .panel h1 { font-size: 17px; margin: 0; letter-spacing: .5px; }
  .panel .sub { margin: 3px 0 0; font-size: 11px; color: #5d7characters; color: #5d7a9c; letter-spacing: .8px; }

  .ctrl-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 6px; }
  .ctrl-head label { font-size: 13px; color: #a8bdd6; }
  .ctrl-head output {
    font: 600 13px ui-monospace, SFMono-Regular, Menlo, monospace;
    color: #4ef0c0;
  }
  input[type=range] {
    width: 100%; height: 4px; -webkit-appearance: none; appearance: none;
    background: #1c2b40; border-radius: 3px; outline: none; display: block;
  }
  input[type=range]::-webkit-slider-thumb {
    -webkit-appearance: none; width: 16px; height: 16px; border-radius: 50%;
    background: #4ef0c0; cursor: pointer; border: 3px solid #0d1523;
    box-shadow: 0 0 0 1px #4ef0c0, 0 0 10px rgba(78,240,192,.5);
  }
  input[type=range]::-moz-range-thumb {
    width: 12px; height: 12px; border-radius: 50%; background: #4ef0c0;
    cursor: pointer; border: 3px solid #0d1523; box-shadow: 0 0 0 1px #4ef0c0;
  }

  .buttons { display: flex; gap: 8px; }
  button {
    flex: 1; padding: 10px 8px; border-radius: 8px; cursor: pointer;
    font-size: 13px; font-weight: 600; letter-spacing: .5px;
    border: 1px solid #24374f; background: #142033; color: #b9cde4;
    transition: .15s;
  }
  button:hover { background: #1a2a42; border-color: #33507a; }
  button.primary {
    background: linear-gradient(180deg,#1fd8a8,#12a37c); color: #04120e;
    border-color: transparent; box-shadow: 0 4px 14px rgba(31,216,168,.25);
  }
  button.primary:hover { filter: brightness(1.1); }

  .readout {
    background: #0a1220; border: 1px solid #172437; border-radius: 10px;
    padding: 4px 12px; font-size: 12.5px;
  }
  .row {
    display: flex; justify-content: space-between; align-items: center;
    padding: 7px 0; border-bottom: 1px solid #131d2c;
  }
  .row:last-child { border-bottom: none; }
  .row span { color: #7e96b3; }
  .row b {
    font: 600 12.5px ui-monospace, SFMono-Regular, Menlo, monospace;
    color: #cfe4ff;
  }
  .row b.accent { color: #4ef0c0; }
  .row b.warn { color: #ffd166; }
  .row.sep { border-bottom: 1px solid #23364e; }

  .hint { font-size: 11px; color: #55708f; line-height: 1.7; }
  .hint code { color: #4aa8ff; font-size: 11px; }

  @media (max-width: 760px) {
    body { flex-direction: column; }
    #stage { flex: 0 0 55vh; }
    .panel { width: 100%; flex: 1 1 auto; border-left: none; border-top: 1px solid #1d2b40; }
  }
</style>
</head>
<body>

<div id="stage"><canvas id="cv"></canvas></div>

<div class="panel">
  <header>
    <h1>平抛运动模拟</h1>
    <p class="sub">HORIZONTAL PROJECTILE MOTION</p>
  </header>

  <section>
    <div class="ctrl">
      <div class="ctrl-head"><label for="v0In">初速度 v₀</label><output id="v0Out">10.0 m/s</output></div>
      <input type="range" id="v0In" min="1" max="40" step="0.5" value="10">
    </div>
    <div class="ctrl" style="margin-top:14px">
      <div class="ctrl-head"><label for="hIn">抛出高度 h</label><output id="hOut">20.0 m</output></div>
      <input type="range" id="hIn" min="1" max="80" step="1" value="20">
    </div>
    <div class="ctrl" style="margin-top:14px">
      <div class="ctrl-head"><label for="gIn">重力加速度 g</label><output id="gOut">9.8 m/s²</output></div>
      <input type="range" id="gIn" min="1.6" max="25" step="0.1" value="9.8">
    </div>
    <div class="ctrl" style="margin-top:14px">
      <div class="ctrl-head"><label for="spIn">播放速度</label><output id="spOut">0.5×</output></div>
      <input type="range" id="spIn" min="0.1" max="1.5" step="0.1" value="0.5">
    </div>
  </section>

  <section class="buttons">
    <button id="playBtn" class="primary">开始</button>
    <button id="resetBtn">重置</button>
  </section>

  <section class="readout">
    <div class="row sep"><span>理论飞行时间</span><b id="rT">2.02 s</b></div>
    <div class="row sep"><span>理论水平射程</span><b id="rR">20.20 m</b></div>
    <div class="row"><span>时间 t</span><b id="rt" class="accent">0.00 s</b></div>
    <div class="row"><span>水平位移 x</span><b id="rx">0.00 m</b></div>
    <div class="row"><span>下落高度 y</span><b id="ry">0.00 m</b></div>
    <div class="row"><span>水平速度 vₓ</span><b id="rvx">10.0 m/s</b></div>
    <div class="row"><span>竖直速度 v_y</span><b id="rvy">0.0 m/s</b></div>
    <div class="row"><span>合速度 v</span><b id="rv" class="warn">10.0 m/s</b></div>
    <div class="row"><span>速度与水平夹角 θ</span><b id="rth">0.0°</b></div>
  </section>

  <p class="hint">
    水平方向匀速：<code>x = v₀t</code><br>
    竖直方向自由落体：<code>y = ½gt²</code><br>
    轨迹方程：<code>y = gx² / (2v₀²)</code>（抛物线）
  </p>
</div>

<script>
/* ================= 状态 ================= */
const S = {
  v0: 10, h: 20, g: 9.8,
  t: 0, running: false, landed: false,
  speed: 0.5
};

const cv  = document.getElementById('cv');
const ctx = cv.getContext('2d');

let W = 800, H = 600, scale = 10, ox = 60, oy = 500;

const flightTime = () => Math.sqrt(2 * S.h / S.g);
const rangeX     = () => S.v0 * flightTime();
const pos        = tt => ({ x: S.v0 * tt, y: S.h - 0.5 * S.g * tt * tt });
const sx = x => ox + x * scale;
const sy = y => oy - y * scale;

/* ================= 尺寸与布局 ================= */
function resize(){
  const rect = cv.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  W = Math.max(1, rect.width);
  H = Math.max(1, rect.height);
  cv.width  = Math.round(W * dpr);
  cv.height = Math.round(H * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  layout();
}

function layout(){
  const padL = 70, padR = 70, padT = 60, padB = 70;
  const availW = Math.max(60, W - padL - padR);
  const availH = Math.max(60, H - padT - padB);

  const R  = Math.max(rangeX(), 0.5);
  const Hh = Math.max(S.h, 0.5);

  scale = Math.min(availW / (R * 1.15), availH / (Hh * 1.3));
  scale = Math.min(scale, 60);
  scale = Math.max(scale, 0.3);

  ox = Math.max(30, (W - R * scale) / 2);
  oy = H - padB;
}

/* ================= 绘制工具 ================= */
function niceStep(minPx){
  const opts = [0.05, 0.1, 0.2, 0.5, 1, 2, 5, 10, 20, 50, 100, 200, 500, 1000];
  for (const s of opts) if (s * scale >= minPx) return s;
  return 2000;
}

function arrow(x1, y1, x2, y2, color, w){
  const dx = x2 - x1, dy = y2 - y1;
  const len = Math.hypot(dx, dy);
  if (len < 4) return;
  const ang = Math.atan2(dy, dx);
  const head = Math.min(11, len * 0.4);

  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = w;
  ctx.lineCap = 'round';

  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2 - Math.cos(ang) * head * 0.6, y2 - Math.sin(ang) * head * 0.6);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - head * Math.cos(ang - 0.42), y2 - head * Math.sin(ang - 0.42));
  ctx.lineTo(x2 - head * Math.cos(ang + 0.42), y2 - head * Math.sin(ang + 0.42));
  ctx.closePath();
  ctx.fill();
}

/* ================= 各层绘制 ================= */
function drawBackground(){
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#0a1322');
  g.addColorStop(1, '#060a11');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  const rg = ctx.createRadialGradient(W * 0.72, H * 0.12, 0, W * 0.72, H * 0.12, Math.max(W, H) * 0.75);
  rg.addColorStop(0, 'rgba(40,95,170,0.20)');
  rg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = rg;
  ctx.fillRect(0, 0, W, H);
}

function drawGrid(){
  const step = niceStep(52);
  const xL = (0 - ox) / scale,  xR = (W - ox) / scale;
  const yB = (oy - H) / scale,  yT = (oy - 0) / scale;

  ctx.lineWidth = 1;
  ctx.strokeStyle = 'rgba(84,140,205,0.11)';
  ctx.beginPath();
  for (let x = Math.ceil(xL / step) * step; x <= xR; x += step){
    const px = sx(x);
    ctx.moveTo(px, 0); ctx.lineTo(px, H);
  }
  for (let y = Math.ceil(yB / step) * step; y <= yT; y += step){
    const py = sy(y);
    if (py < 0 || py > H) continue;
    ctx.moveTo(0, py); ctx.lineTo(W, py);
  }
  ctx.stroke();

  // 地面刻度数字
  ctx.fillStyle = 'rgba(110,150,195,0.55)';
  ctx.font = '11px ui-monospace, Menlo, monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  const gy = sy(0);
  for (let x = Math.ceil(Math.max(xL, 0) / step) * step; x <= xR; x += step){
    if (x === 0) continue;
    ctx.fillText(x.toFixed(step < 1 ? 1 : 0), sx(x), gy + 8);
  }
}

function drawGround(){
  const gy = sy(0);
  const grd = ctx.createLinearGradient(0, gy, 0, H);
  grd.addColorStop(0, 'rgba(42,110,180,0.30)');
  grd.addColorStop(1, 'rgba(42,110,180,0.02)');
  ctx.fillStyle = grd;
  ctx.fillRect(0, gy, W, H - gy);

  ctx.strokeStyle = 'rgba(110,180,255,0.65)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(0, gy);
  ctx.lineTo(W, gy);
  ctx.stroke();
}

function drawTheoryPath(){
  const T = flightTime();
  ctx.save();
  ctx.setLineDash([5, 7]);
  ctx.strokeStyle = 'rgba(120,200,255,0.28)';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  for (let i = 0; i <= 140; i++){
    const p = pos(T * i / 140);
    const X = sx(p.x), Y = sy(p.y);
    i ? ctx.lineTo(X, Y) : ctx.moveTo(X, Y);
  }
  ctx.stroke();
  ctx.restore();
}

function drawTrail(){
  if (S.t <= 0) return;

  ctx.save();
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // 外层辉光
  ctx.strokeStyle = 'rgba(78,240,192,0.18)';
  ctx.lineWidth = 7;
  ctx.beginPath();
  for (let i = 0; i <= 200; i++){
    const p = pos(S.t * i / 200);
    const X = sx(p.x), Y = sy(p.y);
    i ? ctx.lineTo(X, Y) : ctx.moveTo(X, Y);
  }
  ctx.stroke();

  // 主线
  ctx.strokeStyle = '#4ef0c0';
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  for (let i = 0; i <= 200; i++){
    const p = pos(S.t * i / 200);
    const X = sx(p.x), Y = sy(p.y);
    i ? ctx.lineTo(X, Y) : ctx.moveTo(X, Y);
  }
  ctx.stroke();
  ctx.restore();

  // 等时间间隔标记点（体现水平匀速、竖直加速）
  const T = flightTime();
  const dt = T / 10;
  ctx.fillStyle = 'rgba(120,255,220,0.55)';
  for (let i = 1; i < 10; i++){
    const tt = dt * i;
    if (tt > S.t) break;
    const p = pos(tt);
    ctx.beginPath();
    ctx.arc(sx(p.x), sy(p.y), 2.6, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawMarkers(){
  const X0 = sx(0), Y0 = sy(0), Yh = sy(S.h);

  // 高度虚线
  ctx.save();
  ctx.setLineDash([4, 5]);
  ctx.strokeStyle = 'rgba(130,175,225,0.4)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(X0, Yh);
  ctx.lineTo(X0, Y0);
  ctx.stroke();
  ctx.restore();

  // 高度标签
  ctx.fillStyle = 'rgba(150,190,230,0.8)';
  ctx.font = '12px ui-monospace, Menlo, monospace';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'middle';
  const midY = (Y0 + Yh) / 2;
  if (X0 > 60) ctx.fillText(`h=${S.h.toFixed(0)}m`, X0 - 9, midY);

  // 抛出点标记
  ctx.fillStyle = 'rgba(120,200,255,0.85)';
  ctx.beginPath();
  ctx.arc(X0, Yh, 3, 0, Math.PI * 2);
  ctx.fill();

  // 落点标记（落地后显示）
  if (S.landed){
    const lx = sx(rangeX()), ly = sy(0);
    ctx.strokeStyle = 'rgba(255,209,102,0.7)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(lx - 7, ly); ctx.lineTo(lx + 7, ly);
    ctx.stroke();
    ctx.fillStyle = 'rgba(255,209,102,0.9)';
    ctx.beginPath();
    ctx.arc(lx, ly, 3.5, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawBall(){
  const p = pos(S.t);
  const X = sx(p.x), Y = sy(p.y);
  const r = 8.5;

  // 光晕
  const g = ctx.createRadialGradient(X, Y, 0, X, Y, r * 3.4);
  g.addColorStop(0, 'rgba(80,255,200,0.35)');
  g.addColorStop(1, 'rgba(80,255,200,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(X, Y, r * 3.4, 0, Math.PI * 2);
  ctx.fill();

  // 球体
  const b = ctx.createRadialGradient(X - r * 0.35, Y - r * 0.4, r * 0.1, X, Y, r);
  b.addColorStop(0, '#eafffb');
  b.addColorStop(0.45, '#4ef0c0');
  b.addColorStop(1, '#12996f');
  ctx.fillStyle = b;
  ctx.beginPath();
  ctx.arc(X, Y, r, 0, Math.PI * 2);
  ctx.fill();
}

function drawVelocityArrow(){
  const p = pos(S.t);
  const X = sx(p.x), Y = sy(p.y);
  const vx = S.v0, vy = S.g * S.t;

  const vmax = Math.max(vx, vy, 1);
  const k = Math.min(2.0, 110 / vmax);   // 像素 / (m/s)

  // 合速度
  if (vx * k > 5 || vy * k > 5){
    arrow(X, Y, X + vx * k, Y + vy * k, '#ffd166', 2.2);
  }

  // 分量（细线）
  ctx.save();
  ctx.setLineDash([3, 4]);
  ctx.strokeStyle = 'rgba(74,168,255,0.55)';
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(X, Y);
  ctx.lineTo(X + vx * k, Y);
  ctx.stroke();

  ctx.strokeStyle = 'rgba(255,159,67,0.6)';
  ctx.beginPath();
  ctx.moveTo(X, Y);
  ctx.lineTo(X, Y + vy * k);
  ctx.stroke();

  // 平行四边形虚线
  ctx.strokeStyle = 'rgba(255,209,102,0.22)';
  ctx.beginPath();
  ctx.moveTo(X + vx * k, Y);
  ctx.lineTo(X + vx * k, Y + vy * k);
  ctx.moveTo(X, Y + vy * k);
  ctx.lineTo(X + vx * k, Y + vy * k);
  ctx.stroke();
  ctx.restore();
}

/* ================= 主绘制 ================= */
function draw(){
  ctx.clearRect(0, 0, W, H);
  drawBackground();
  drawGrid();
  drawGround();
  drawTheoryPath();
  drawTrail();
  drawMarkers();
  drawBall();
  drawVelocityArrow();
}

/* ================= 数据显示 ================= */
const cache = {};
function txt(id, s){
  if (cache[id] !== s){
    cache[id] = s;
    const el = document.getElementById(id);
    if (el) el.textContent = s;
  }
}

function updateReadout(){
  const p  = pos(S.t);
  const vx = S.v0;
  const vy = S.g * S.t;
  const v  = Math.hypot(vx, vy);
  const ang = Math.atan2(vy, vx) * 180 / Math.PI;

  txt('rt',  S.t.toFixed(2) + ' s');
  txt('rx',  p.x.toFixed(2) + ' m');
  txt('ry',  (S.h - p.y).toFixed(2) + ' m');
  txt('rvx', vx.toFixed(1) + ' m/s');
  txt('rvy', vy.toFixed(1) + ' m/s');
  txt('rv',  v.toFixed(1) + ' m/s');
  txt('rth', ang.toFixed(1) + '°');
}

function updateStatic(){
  txt('rT', flightTime().toFixed(2) + ' s');
  txt('rR', rangeX().toFixed(2) + ' m');
}

/* ================= 控制逻辑 ================= */
const playBtn  = document.getElementById('playBtn');
const resetBtn = document.getElementById('resetBtn');

function updateButton(){
  playBtn.textContent = S.running ? '暂停' : (S.landed ? '重播' : '开始');
}

function restart(){
  S.t = 0;
  S.landed = false;
  S.running = false;
  layout();
  updateButton();
  updateReadout();
}

playBtn.addEventListener('click', () => {
  if (S.landed || S.t >= flightTime()){
    S.t = 0;
    S.landed = false;
    S.running = true;
  } else {
    S.running = !S.running;
  }
  updateButton();
});

resetBtn.addEventListener('click', restart);

/* 参数滑块 */
const v0In = document.getElementById('v0In');
const hIn  = document.getElementById('hIn');
const gIn  = document.getElementById('gIn');
const spIn = document.getElementById('spIn');

v0In.addEventListener('input', e => {
  S.v0 = +e.target.value;
  document.getElementById('v0Out').textContent = S.v0.toFixed(1) + ' m/s';
  restart();
  updateStatic();
});

hIn.addEventListener('input', e => {
  S.h = +e.target.value;
  document.getElementById('hOut').textContent = S.h.toFixed(1) + ' m';
  restart();
  updateStatic();
});

gIn.addEventListener('input', e => {
  S.g = +e.target.value;
  document.getElementById('gOut').textContent = S.g.toFixed(1) + ' m/s²';
  restart();
  updateStatic();
});

spIn.addEventListener('input', e => {
  S.speed = +e.target.value;
  document.getElementById('spOut').textContent = S.speed.toFixed(1) + '×';
});

/* ================= 动画循环 ================= */
let last = performance.now();

function frame(now){
  let dt = (now - last) / 1000;
  last = now;
  if (dt > 0.1) dt = 0.1;      // 防止切标签页后跳帧

  if (S.running && !S.landed){
    S.t += dt * S.speed;
    const T = flightTime();
    if (S.t >= T){
      S.t = T;
      S.landed = true;
      S.running = false;
      updateButton();
    }
  }

  draw();
  updateReadout();
  requestAnimationFrame(frame);
}

/* ================= 初始化 ================= */
function init(){
  resize();
  updateStatic();
  updateReadout();
  updateButton();
  requestAnimationFrame(frame);
}

window.addEventListener('resize', resize);
if (window.ResizeObserver){
  new ResizeObserver(resize).observe(document.getElementById('stage'));
}

init();
</script>
</body>
</html>
