      guessBtn.disabled = false;

      countEl.textContent = "0";
      message.textContent = "请开始你的第一次猜测！";
      message.className = "message";
      historyEl.textContent = "猜测记录：暂无";

      input.focus();
    }

    function updateHistory() {
      if (history.length === 0) {
        historyEl.textContent = "猜测记录：暂无";
      } else {
        historyEl.textContent = "猜测记录：" + history.join("、");
      }
    }

    function guess() {
      if (gameOver) return;

      const value = Number(input.value);

      if (!Number.isInteger(value) || value < 1 || value > 100) {
        message.textContent = "请输入 1 到 100 之间的整数！";
        message.className = "message fail";
        input.value = "";
        input.focus();
        return;
      }

      count++;
      countEl.textContent = count;
      history.push(value);
      updateHistory();

      if (value === answer) {
        gameOver = true;
        message.textContent = `🎉 恭喜你！猜对了！答案就是 ${answer}，共用了 ${count} 次。`;
        message.className = "message win";
        input.disabled = true;
        guessBtn.disabled = true;
      } else if (value < answer) {
        message.textContent = `太小了！再试试更大的数字。`;
        message.className = "message";
        input.value = "";
        input.focus();
      } else {
        message.textContent = `太大了！再试试更小的数字。`;
        message.className = "message";
        input.value = "";
        input.focus();
      }
    }

    guessBtn.addEventListener("click", guess);

    input.addEventListener("keydown", function (event) {
      if (event.key === "Enter") {
        guess();
      }
    });

    restartBtn.addEventListener("click", initGame);

    initGame();
  </script>
</body>
</html>
```

玩法说明：

- 系统随机生成一个 **1 到 100** 的整数。
- 你输入数字后点击“猜一猜”，或按回车。
- 系统会提示“太大了”或“太小了”。
- 猜中后会显示总次数。
- 点击“重新开始”可以重新生成数字。
